namespace Subro.RecordForge;

using System;
using System.Collections.Generic;
using System.Linq.Expressions;

/// <summary>
/// A property of a generated type, as its interface declares it: what a reader of metadata needs without reflection.
/// </summary>
/// <remarks>
/// <para>
/// Every type generated by <see cref="GenerateRecordAttribute"/> lists its properties in a static <c>Fields</c>, in the
/// order of the interfaces (a base interface's first) and of their declarations.
/// </para>
/// <para>
/// <see cref="Attributes"/> are the attributes written on the interface's property, created again as instances, so a
/// library can read its own (<c>[Search]</c>, <c>[Required]</c>) without knowing RecordForge and RecordForge without
/// knowing it. Compiler attributes, and attributes the generated code cannot reach, are left out.
/// </para>
/// </remarks>
public abstract class RecordField
{
    private protected RecordField(string name, Type type, Type declaringInterface, LambdaExpression expression,
        bool allowsNull, bool hasSetter, IReadOnlyList<Attribute> attributes, IReadOnlyList<Attribute> interfaceAttributes)
    {
        Name = name;
        Type = type;
        DeclaringInterface = declaringInterface;
        Expression = expression;
        AllowsNull = allowsNull;
        HasSetter = hasSetter;
        Attributes = attributes;
        InterfaceAttributes = interfaceAttributes;
    }

    /// <summary>The property's name.</summary>
    public string Name { get; }

    /// <summary>The property's type. A nullable reference type is its type itself; see <see cref="AllowsNull"/>.</summary>
    public Type Type { get; }

    /// <summary>The interface that declares the property: the generated type's own, or one it inherits.</summary>
    public Type DeclaringInterface { get; }

    /// <summary>
    /// The property read from the interface that declares it, <c>(IClubCode x) =&gt; x.Name</c>: for building a query over
    /// anything that implements that interface.
    /// </summary>
    public LambdaExpression Expression { get; }

    /// <summary>Whether the property may hold null: a nullable value type, or a reference type annotated as nullable.</summary>
    public bool AllowsNull { get; }

    /// <summary>Whether the interface lets the property be written: a <c>set</c> or an <c>init</c>.</summary>
    public bool HasSetter { get; }

    /// <summary>The attributes on the interface's property, in the order they are written.</summary>
    public IReadOnlyList<Attribute> Attributes { get; }

    /// <summary>The attributes on <see cref="DeclaringInterface"/> itself, such as a group its fields belong to.</summary>
    public IReadOnlyList<Attribute> InterfaceAttributes { get; }

    /// <summary>The property's value on <paramref name="source"/>, which implements <see cref="DeclaringInterface"/>.</summary>
    public abstract object? GetValue(object source);

    /// <summary>The first attribute of type <typeparamref name="TAttribute"/> on the property, or null.</summary>
    public TAttribute? GetAttribute<TAttribute>() where TAttribute : Attribute
    {
        foreach (var attribute in Attributes)
            if (attribute is TAttribute found)
                return found;
        return null;
    }

    /// <summary>Every attribute of type <typeparamref name="TAttribute"/> on the property.</summary>
    public IEnumerable<TAttribute> GetAttributes<TAttribute>() where TAttribute : Attribute
    {
        foreach (var attribute in Attributes)
            if (attribute is TAttribute found)
                yield return found;
    }

    /// <summary>Whether the property has an attribute of type <typeparamref name="TAttribute"/>.</summary>
    public bool HasAttribute<TAttribute>() where TAttribute : Attribute => GetAttribute<TAttribute>() is not null;

    /// <summary>The first attribute of type <typeparamref name="TAttribute"/> on <see cref="DeclaringInterface"/>, or null.</summary>
    public TAttribute? GetInterfaceAttribute<TAttribute>() where TAttribute : Attribute
    {
        foreach (var attribute in InterfaceAttributes)
            if (attribute is TAttribute found)
                return found;
        return null;
    }

    public override string ToString() => Name;

    /// <summary>A field, typed; what the generated code calls.</summary>
    /// <param name="name">The property's name.</param>
    /// <param name="expression">The property read from its interface.</param>
    /// <param name="get">The same, compiled by the compiler rather than at run time.</param>
    /// <param name="allowsNull">Whether the property may hold null.</param>
    /// <param name="hasSetter">Whether the interface lets the property be written.</param>
    /// <param name="attributes">The attributes on the interface's property.</param>
    /// <param name="interfaceAttributes">The attributes on the interface.</param>
    public static RecordField<TInterface, TValue> Create<TInterface, TValue>(string name,
        Expression<Func<TInterface, TValue>> expression, Func<TInterface, TValue> get,
        bool allowsNull, bool hasSetter, Attribute[] attributes, Attribute[] interfaceAttributes)
        => new(name, expression, get, allowsNull, hasSetter, attributes, interfaceAttributes);
}

/// <summary>A <see cref="RecordField"/> of a property of type <typeparamref name="TValue"/> on <typeparamref name="TInterface"/>.</summary>
public sealed class RecordField<TInterface, TValue> : RecordField
{
    private readonly Func<TInterface, TValue> get;

    internal RecordField(string name, Expression<Func<TInterface, TValue>> expression, Func<TInterface, TValue> get,
        bool allowsNull, bool hasSetter, IReadOnlyList<Attribute> attributes, IReadOnlyList<Attribute> interfaceAttributes)
        : base(name, typeof(TValue), typeof(TInterface), expression, allowsNull, hasSetter, attributes, interfaceAttributes)
    {
        this.get = get;
    }

    /// <inheritdoc cref="RecordField.Expression"/>
    public new Expression<Func<TInterface, TValue>> Expression => (Expression<Func<TInterface, TValue>>)base.Expression;

    /// <summary>The property's value on <paramref name="source"/>.</summary>
    public TValue Get(TInterface source) => get(source);

    public override object? GetValue(object source) => get((TInterface)source);
}
